import type { AcpMessage } from './json-rpc.js'
import type { BridgeHelloParams, BridgeLifecycleEvent } from './bridge-messages.js'

// ─── Server Configuration ────────────────────────────────────────────────────

/** Options for constructing an AgentletServer instance */
export interface AgentletServerOptions {
  /**
   * Validate the token and agent from bridge/hello.
   * Throw an Error to reject the connection.
   *
   * The agentId (from bridge/hello) is used as the primary key automatically.
   * This callback only validates — it does NOT assign identity.
   *
   * @param token - The authentication token from bridge/hello
   * @param meta - The full bridge/hello params (includes agentId, agent info, etc.)
   * @returns Optional metadata to attach to the connection
   */
  authenticate: (token: string, meta: BridgeHelloParams) => Promise<AuthResult>

  /** Called when a new agent connects for the first time */
  onConnection?: (agent: AgentConnection) => void

  /** Called when a previously disconnected agent reconnects (same agentId) */
  onReconnection?: (agent: AgentConnection) => void

  /** Called when an agent disconnects (network drop or graceful goodbye) */
  onDisconnection?: (agent: AgentConnection, reason: string) => void

  /** Max time (ms) to wait for bridge/hello after WebSocket opens. Default: 10000 */
  handshakeTimeout?: number

  /** Max messages buffered per connection for replay on reconnection. Default: 100 */
  outboundBufferLimit?: number
}

/** Result returned by the authenticate callback */
export interface AuthResult {
  /**
   * Application-specific metadata (user info, project, permissions, etc.)
   * Stored on AgentConnection.metadata and available to host app.
   */
  metadata?: Record<string, unknown>
}

// ─── AgentConnection ──────────────────────────────────────────────────────────

/** Represents a connected (or recently-disconnected) agent in the server registry */
export interface AgentConnection {
  /**
   * Globally unique agent identifier, generated by the agent-side adapter.
   * Format: "<hostname>:<executable>:<cwd-basename>:<8-char-uuid>"
   * Stable across WebSocket reconnections; changes on bridge process restart.
   */
  readonly agentId: string

  /** The token used to authenticate this connection */
  readonly token: string

  /** Application-specific metadata (from AuthResult.metadata) */
  readonly metadata: Record<string, unknown>

  /** Agent process info (from bridge/hello) */
  readonly agentInfo: { command: string; pid: number; cwd: string }

  /** Active ACP session info (from bridge/hello session bootstrap) */
  readonly session?: {
    /** The active ACP sessionId */
    sessionId: string
    /** Whether the agent supports session/load */
    supportsLoad: boolean
    /** The full ACP initialize response (agent capabilities, info, protocol version) */
    initializeResult: unknown
  }

  /** Machine info (from bridge/hello, if provided) */
  readonly machine?: { hostname: string; platform: string }

  /** Bridge identity (from bridge/hello) */
  readonly bridge: { name: string; version: string }

  /** Bridge capabilities (from bridge/hello) */
  readonly capabilities: { autoRestart: boolean; bufferLimit: number }

  /** Current connection state */
  readonly status: 'connected' | 'disconnected'

  /** When this connection was first established */
  readonly connectedAt: Date

  /**
   * Send an ACP message to the agent.
   * If disconnected, message is buffered for replay on reconnection.
   * Throws if the outbound buffer is full.
   */
  send(message: AcpMessage): void

  /** Register handler for ACP messages from the agent */
  onMessage(handler: (message: AcpMessage) => void): void

  /** Register handler for bridge lifecycle events */
  onLifecycle(handler: (event: BridgeLifecycleEvent) => void): void

  /** Request graceful disconnect (sends bridge/shutdown to agent-side adapter) */
  disconnect(reason?: string): void
}
